using SolemateKicks;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;

namespace SolemateKicks
{
    /// <summary>
    /// All database work for the Requisition module, using the DBML (LINQ to SQL designer) context.
    /// SolemateDataContext, AppUser, Brand and the usp_xxxResult classes are GENERATED by Solemate.dbml.
    /// Every method calls one stored procedure (dragged onto the designer) and converts the
    /// generated result rows into the simple classes the forms use (see ViewModels.cs).
    /// Errors raised by THROW in SQL arrive here as exceptions whose Message is the SQL text.
    /// </summary>
    public static class RequisitionService
    {
        // ==================================================================
        //  Login
        // ==================================================================
        public static AppUser Authenticate(string username, string password)
        {
            string hash = PasswordHelper.Hash(password);
            using (SolemateDataContext db = new SolemateDataContext())
            {
                var r = db.usp_Authenticate(username, hash).ToList().FirstOrDefault();
                if (r == null) return null;

                return new AppUser
                {
                    UserId = Convert.ToInt32(r.UserId),
                    Username = r.Username,
                    PasswordHash = r.PasswordHash,
                    FullName = r.FullName,
                    Role = r.Role,
                    Branch = r.Branch
                };
            }
        }

        // ==================================================================
        //  Catalog
        // ==================================================================
        public static List<Brand> GetBrands()
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetBrands().ToList()
                    .Select(b => new Brand { BrandId = Convert.ToInt32(b.BrandId), BrandName = b.BrandName })
                    .ToList();
            }
        }

        public static List<CatalogRow> GetCatalog()
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetCatalog().ToList().Select(p => new CatalogRow
                {
                    ProductId = Convert.ToInt32(p.ProductId),
                    BrandId = Convert.ToInt32(p.BrandId),
                    Sku = p.Sku,
                    Brand = p.Brand,
                    Product = p.Product,
                    Size = Convert.ToInt32(p.Size),
                    Price = Convert.ToDecimal(p.Price),
                    Stock = Convert.ToInt32(p.Stock),
                    ReorderLevel = Convert.ToInt32(p.ReorderLevel)
                }).ToList();
            }
        }

        // ==================================================================
        //  Create / revise / cancel (cashier or manager)
        // ==================================================================
        public static string Create(AppUser user, IEnumerable<CartLine> lines, string remarks)
        {
            string xml = ToItemsXml(ValidateLines(lines));

            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_CreateRequisition(user.UserId, CleanRemarks(remarks), xml).ToList().First().RefNo;
            }
        }

        public static void Revise(int requisitionId, AppUser user, IEnumerable<CartLine> lines, string remarks)
        {
            string xml = ToItemsXml(ValidateLines(lines));

            using (SolemateDataContext db = new SolemateDataContext())
            {
                db.usp_ReviseRequisition(requisitionId, user.UserId, CleanRemarks(remarks), xml);
            }
        }

        public static void Cancel(int requisitionId, AppUser user)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                db.usp_CancelRequisition(requisitionId, user.UserId);
            }
        }

        // ==================================================================
        //  Approve / reject (head)
        // ==================================================================
        public static ApprovalResult Approve(int requisitionId, AppUser head)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                var rows = db.usp_ApproveRequisition(requisitionId, head.UserId).ToList();

                var shortages = rows.Where(r => Convert.ToInt32(r.Available) < Convert.ToInt32(r.Requested)).ToList();

                return new ApprovalResult
                {
                    RefNo = rows[0].RefNo,
                    AllAvailable = shortages.Count == 0,
                    Summary = rows[0].StockCheck,
                    Shortages = shortages.Select(s => string.Format("{0}  {1} (US {2}): requested {3}, available {4}",
                                    s.Sku, s.ProductName, s.Size, s.Requested, s.Available)).ToList()
                };
            }
        }

        public static void Reject(int requisitionId, AppUser head, string reason)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                db.usp_RejectRequisition(requisitionId, head.UserId, reason);
            }
        }

        // ==================================================================
        //  Lists for the main screen
        // ==================================================================
        public static List<RequisitionRow> GetRequisitions(AppUser viewer, string status)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetRequisitions(viewer.UserId, status).ToList().Select(r => new RequisitionRow
                {
                    RequisitionId = Convert.ToInt32(r.RequisitionId),
                    RefNo = r.RefNo,
                    DateCreated = Convert.ToDateTime(r.DateCreated),
                    RequestedById = Convert.ToInt32(r.RequestedById),
                    RequestedBy = r.RequestedBy,
                    Branch = r.Branch,
                    Status = r.Status,
                    Lines = Convert.ToInt32(r.Lines),
                    TotalQty = Convert.ToInt32(r.TotalQty),
                    ReviewedBy = r.ReviewedBy,
                    Remarks = r.Remarks,
                    RejectReason = r.RejectReason,
                    StockCheck = r.StockCheck
                }).ToList();
            }
        }

        public static List<RequisitionLineRow> GetLines(int requisitionId)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetRequisitionLines(requisitionId).ToList().Select(l => new RequisitionLineRow
                {
                    Sku = l.Sku,
                    Brand = l.Brand,
                    Product = l.Product,
                    Size = Convert.ToInt32(l.Size),
                    Quantity = Convert.ToInt32(l.Quantity),
                    Available = Convert.ToInt32(l.Available)
                }).ToList();
            }
        }

        public static RevisionData GetForRevision(int requisitionId)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                var header = db.usp_GetRequisitionHeader(requisitionId).ToList().FirstOrDefault();
                if (header == null) throw new InvalidOperationException("Requisition not found.");

                List<CartLine> lines = db.usp_GetRevisionLines(requisitionId).ToList().Select(l => new CartLine
                {
                    ProductId = Convert.ToInt32(l.ProductId),
                    Sku = l.Sku,
                    Brand = l.Brand,
                    Product = l.Product,
                    Size = Convert.ToInt32(l.Size),
                    Stock = Convert.ToInt32(l.Stock),
                    Quantity = Convert.ToInt32(l.Quantity)
                }).ToList();

                return new RevisionData { RefNo = header.RefNo, Remarks = header.Remarks, Status = header.Status, Lines = lines };
            }
        }

        // ==================================================================
        //  Banner counts
        // ==================================================================
        public static int GetPendingCount()
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetPendingCount();
            }
        }

        public static int GetRejectedCount(int userId)
        {
            using (SolemateDataContext db = new SolemateDataContext())
            {
                return db.usp_GetRejectedCount(userId);
            }
        }

        // ==================================================================
        //  Helpers
        // ==================================================================
        private static List<CartLine> ValidateLines(IEnumerable<CartLine> lines)
        {
            List<CartLine> list = lines.ToList();

            if (list.Count == 0)
                throw new InvalidOperationException("Add at least one item to the requisition.");
            if (list.Any(l => l.Quantity < 1))
                throw new InvalidOperationException("Every quantity must be at least 1.");

            return list;
        }

        private static string ToItemsXml(IEnumerable<CartLine> items)
        {
            XElement root = new XElement("Items",
                items.Select(l => new XElement("Item",
                    new XAttribute("ProductId", l.ProductId),
                    new XAttribute("Quantity", l.Quantity))));
            return root.ToString(SaveOptions.DisableFormatting);
        }

        private static string CleanRemarks(string remarks)
        {
            return string.IsNullOrWhiteSpace(remarks) ? null : remarks.Trim();
        }
    }
}
